1.reproduce_code:
# 1. Initialize a new project and install ESLint v6.8.0
mkdir eslint-bug && cd eslint-bug
npm init -y
npm install eslint@6.8.0 --save-dev

# 2. Create .eslintrc.js with the rules as in the bug report
cat > .eslintrc.js << 'EOF'
module.exports = {
    env: {
        browser: true,
        es6: true
    },
    extends: "eslint:recommended",
    globals: {
        Atomics: "readonly",
        SharedArrayBuffer: "readonly"
    },
    parserOptions: {
        ecmaVersion: 2018,
        sourceType: "module"
    },
    rules: {
        "prefer-const": "error",
        "no-undef-init": "warn"
    }
};
EOF

# 3. Create a test file that triggers the bug
cat > testfile.js << 'EOF'
let foo = undefined;
EOF

# 4. Run ESLint with --fix
npx eslint --fix testfile.js

# 5. Inspect the result
# You will see that testfile.js has been transformed to:
#     const foo;
# which is invalid because constants must be initialized.
